#include <iostream>

class Counter {
    // Good Practice: friend declarations placed first
    friend void setSecretValue(Counter &c, int val);

public:
    Counter() : value(0) {}
    void print() const {
        std::cout << "Value = " << value << "\n";
    }

private:
    int value;
};

// Standalone non-member function granted friend access
void setSecretValue(Counter &c, int val) {
    c.value = val; // Direct access to private member
}

int main() {
    Counter cnt;
    cnt.print();
    setSecretValue(cnt, 42); // Called as global function with object handle
    cnt.print();
    return 0;
}

#include <iostream>

class Coordinate {
public:
    Coordinate(int x, int y) {
        // Resolving parameter shadowing with this->
        this->x = x;
        this->y = y;
    }

    void print() const {
        // Implicit access
        std::cout << "Implicit: (" << x << ", " << y << ")\n";
        // Explicit access via ->
        std::cout << "Explicit this->: (" << this->x << ", " << this->y << ")\n";
        // Explicit access via dereferenced (*this).
        std::cout << "Explicit (*this).: (" << (*this).x << ", " << (*this).y << ")\n";
    }

private:
    int x;
    int y;
};

int main() {
    Coordinate pt(15, 30);
    pt.print();
    std::cout << "sizeof(Coordinate) = " << sizeof(Coordinate) 
              << " (equals sizeof 2 ints, this is not stored in object)\n";
    return 0;
}
